#!/usr/bin/env python3
"""Minimal SVG-subset rasterizer for SEAM verification of the 4 env layers.
Renders each layer, asserts col[0]==col[W-1] (the tiling seam condition), and
writes a 2x-wide tiled PNG (two copies side-by-side) for visual inspection.
Covers ONLY the primitives used in these SVGs: rect (solid / vertical linearGrad /
radialGrad), circle (radialGrad), ellipse (solid / alpha), path (M/L/H/V/C/Q/Z solid),
g, use(translate), defs. objectBoundingBox gradients assumed for url() fills."""
import sys, re, math
import xml.etree.ElementTree as ET
from PIL import Image, ImageDraw

NS = '{http://www.w3.org/2000/svg}'
def tag(e): return e.tag.replace(NS, '')

def hx(c):
    c = c.strip().lstrip('#')
    if len(c) == 3: c = ''.join(ch*2 for ch in c)
    return (int(c[0:2],16), int(c[2:4],16), int(c[4:6],16))

def stops_of(grad):
    out = []
    for s in grad:
        if tag(s) != 'stop': continue
        off = float(s.get('offset', '0'))
        col = hx(s.get('stop-color', '#000000'))
        a = float(s.get('stop-opacity', '1'))
        out.append((off, col[0], col[1], col[2], a))
    out.sort()
    return out

def lerp_stops(stops, t):
    if t <= stops[0][0]: s = stops[0]
    elif t >= stops[-1][0]: s = stops[-1]
    else:
        for i in range(len(stops)-1):
            if stops[i][0] <= t <= stops[i+1][0]:
                a, b = stops[i], stops[i+1]
                u = (t-a[0])/(b[0]-a[0]) if b[0]!=a[0] else 0
                return (a[1]+(b[1]-a[1])*u, a[2]+(b[2]-a[2])*u, a[3]+(b[3]-a[3])*u, a[4]+(b[4]-a[4])*u)
        s = stops[-1]
    return (s[1], s[2], s[3], s[4])

class Doc:
    def __init__(self, root, W, H):
        self.grads = {}; self.symbols = {}
        self.W, self.H = W, H
        for el in root.iter():
            if tag(el) in ('linearGradient','radialGradient'):
                self.grads['#'+el.get('id')] = el
            if tag(el) in ('g',) and el.get('id'):
                self.symbols['#'+el.get('id')] = el

    def fill_for(self, el, bbox):
        f = el.get('fill', '#000')
        a = float(el.get('opacity', el.get('fill-opacity', '1')))
        if f.startswith('url('):
            gid = re.search(r'url\((#[^)]+)\)', f).group(1)
            g = self.grads[gid]
            kind = tag(g)
            sts = stops_of(g)
            if kind == 'linearGradient':
                # vertical only (x1==x2); objectBoundingBox y1=0..y2=1
                def col_at(px, py):
                    t = (py - bbox[1]) / (bbox[3] - bbox[1]) if bbox[3] != bbox[1] else 0
                    return lerp_stops(sts, t)
                return ('func_v', col_at, a)
            else:  # radial, objectBoundingBox cx=cy=.5 r=.5
                x0,y0,w,h = bbox
                def col_at(px, py):
                    nx = (px - x0) / w if w else 0
                    ny = (py - y0) / h if h else 0
                    d = math.hypot(nx-0.5, ny-0.5) / 0.5
                    return lerp_stops(sts, min(d, 1.0))
                return ('func_r', col_at, a)
        else:
            return ('solid', hx(f), a)

def parse_path(d):
    """Return list of (cmd, nums)."""
    cmds = re.findall(r'[MmLlHhVvCcQqZz]', d)
    nums = [float(x) for x in re.findall(r'-?\d*\.?\d+(?:[eE][-+]?\d+)?', d)]
    out = []; ni = 0
    for c in cmds:
        if c in 'Zz': out.append((c, []))
        elif c in 'HhVv': n=1
        elif c in 'MmLlTt': n=2
        elif c in 'QqSs': n=4
        elif c in 'Cc': n=6
        else: n=2
        out.append((c, nums[ni:ni+n])); ni += n
    return out

def bez_polygons(d, ox=0.0, oy=0.0):
    """Sample an SVG path into a list of polygons (one per subpath)."""
    poly = []; polys = []
    x = y = 0.0; sx = sy = 0.0
    def sample_cubic(p0,p1,p2,p3,N=24):
        pts=[]
        for i in range(N+1):
            t=i/N; mt=1-t
            u=mt*mt*mt; v=3*mt*mt*t; w=3*mt*t*t; z=t*t*t
            pts.append((u*p0[0]+v*p1[0]+w*p2[0]+z*p3[0],
                        u*p0[1]+v*p1[1]+w*p2[1]+z*p3[1]))
        return pts
    def sample_quad(p0,p1,p2,N=18):
        pts=[]
        for i in range(N+1):
            t=i/N;mt=1-t
            pts.append((mt*mt*p0[0]+2*mt*t*p1[0]+t*t*p2[0],
                        mt*mt*p0[1]+2*mt*t*p1[1]+t*t*p2[1]))
        return pts
    for c, ns in parse_path(d):
        C = c.upper()
        if C == 'M':
            if poly: polys.append(poly)
            poly = []
            x, y = (ns[0]+ox, ns[1]+oy) if c.isupper() else (x+ns[0], y+ns[1])
            sx, sy = x, y; poly.append((x,y))
        elif C == 'L':
            nx = ns[0]+ox if c.isupper() else x+ns[0]
            ny = ns[1]+oy if c.isupper() else y+ns[1]
            poly.append((nx,ny)); x,y = nx,ny
        elif C == 'H':
            nx = ns[0]+ox if c.isupper() else x+ns[0]; poly.append((nx,y)); x = nx
        elif C == 'V':
            ny = ns[1]+oy if c.isupper() else y+ns[0]
            # note: V takes one number
            ny = ns[0]+oy if c.isupper() else y+ns[0]; poly.append((x,ny)); y = ny
        elif C == 'C':
            p0=(x,y)
            if c.isupper(): pts=[(p[0]+ox,p[1]+oy) for p in [(ns[0],ns[1]),(ns[2],ns[3]),(ns[4],ns[5])]]
            else: pts=[(x+ns[0],y+ns[1]),(x+ns[2],y+ns[3]),(x+ns[4],y+ns[5])]
            poly += sample_cubic(p0,pts[0],pts[1],pts[2]); x,y = pts[2]
        elif C == 'Q':
            p0=(x,y)
            if c.isupper(): pts=[(p[0]+ox,p[1]+oy) for p in [(ns[0],ns[1]),(ns[2],ns[3])]]
            else: pts=[(x+ns[0],y+ns[1]),(x+ns[2],y+ns[3])]
            poly += sample_quad(p0,pts[0],pts[1]); x,y = pts[1]
        elif C == 'Z':
            poly.append((sx,sy)); polys.append(poly); poly=[]; x,y = sx,sy
    if poly: polys.append(poly)
    return polys

def draw_path(img, el, ox, oy, doc):
    f = el.get('fill', '#000')
    if f == 'none': return
    for poly in bez_polygons(el.get('d',''), ox, oy):
        if len(poly) >= 3:
            ImageDraw.Draw(img).polygon(poly, fill=hx(f))

def prim_bbox_for(kind, ns, ox, oy):
    # returns bbox (x0,y0,x1,y1)
    if kind == 'rect':
        x,y,w,h = ns[0]+ox, ns[1]+oy, ns[2], ns[3]
        return (x,y,x+w,y+h)
    if kind == 'ellipse':
        return (ns[0]-ns[2]+ox, ns[1]-ns[3]+oy, ns[0]+ns[2]+ox, ns[1]+ns[3]+oy)
    if kind == 'circle':
        return (ns[0]-ns[2]+ox, ns[1]-ns[2]+oy, ns[0]+ns[2]+ox, ns[1]+ns[2]+oy)
    return (0,0,1,1)

def draw_shape(img, el, ox, oy, doc):
    k = tag(el)
    if k == 'g':
        for ch in el: draw_shape(img, ch, ox, oy, doc)
        return
    if k == 'use':
        href = el.get('href') or el.get(NS+'href')
        sym = doc.symbols.get(href)
        if sym is None: return
        tr = el.get('transform','')
        m = re.search(r'translate\(([-\d.]+)[\s,]+([-\d.]+)\)', tr)
        tx, ty = (float(m.group(1)), float(m.group(2))) if m else (0,0)
        # apply use opacity to children via group alpha handled simply: pass through
        for ch in sym: draw_shape(img, ch, ox+tx, oy+ty, doc)
        return
    if k not in ('rect','ellipse','circle','path'): return
    # gather numeric attrs
    if k == 'rect':
        ns = [float(el.get(a,'0')) for a in ('x','y','width','height')]
    elif k == 'ellipse':
        ns = [float(el.get(a,'0')) for a in ('cx','cy','rx','ry')]
    elif k == 'circle':
        ns = [float(el.get(a,'0')) for a in ('cx','cy','r')]
    else:
        draw_path(img, el, ox, oy, doc); return
    fill = el.get('fill', '#000')
    opacity = float(el.get('opacity', el.get('fill-opacity','1')))
    bbox = prim_bbox_for(k, ns, ox, oy)
    finfo = doc.fill_for(el, bbox)
    x0,y0,x1,y1 = [int(round(v)) for v in bbox]
    d = ImageDraw.Draw(img)
    if finfo[0] == 'solid':
        col = finfo[1]
        if opacity >= 0.999:
            _draw_prim(d, k, ns, ox, oy, col)
        else:
            tmp = Image.new('RGBA', img.size, (0,0,0,0))
            td = ImageDraw.Draw(tmp)
            _draw_prim(td, k, ns, ox, oy, col)
            tmp.putalpha(int(opacity*255))
            img.alpha_composite(tmp)
    elif finfo[0] == 'func_v':  # vertical linear gradient on a rect
        col_at, a = finfo[1], finfo[2]
        for py in range(y0, y1):
            r,g,b,al = col_at(x0, py)
            al = al*a
            if al >= 0.999:
                d.line([(x0,py),(x1-1,py)], fill=(int(r),int(g),int(b)))
            else:
                tmp = Image.new('RGBA', img.size, (0,0,0,0))
                ImageDraw.Draw(tmp).line([(x0,py),(x1-1,py)], fill=(int(r),int(g),int(b)))
                tmp.putalpha(int(al*255)); img.alpha_composite(tmp)
    elif finfo[0] == 'func_r':  # radial gradient (circle)
        col_at, a = finfo[1], finfo[2]
        cx, cy, r = ns[0]+ox, ns[1]+oy, ns[2]
        tmp = Image.new('RGBA', img.size, (0,0,0,0))
        tp = tmp.load()
        for py in range(max(0,y0), min(img.size[1], y1)):
            for px in range(max(0,x0), min(img.size[0], x1)):
                rr,gg,bb,al = col_at(px, py)
                if al <= 0: continue
                tp[px,py] = (int(rr),int(gg),int(bb), int(al*a*255))
        img.alpha_composite(tmp)

def _draw_prim(d, k, ns, ox, oy, col):
    if k == 'rect':
        d.rectangle([ns[0]+ox, ns[1]+oy, ns[0]+ox+ns[2], ns[1]+oy+ns[3]], fill=col)
    elif k == 'ellipse':
        d.ellipse([ns[0]-ns[2]+ox, ns[1]-ns[3]+oy, ns[0]+ns[2]+ox, ns[1]+ns[3]+oy], fill=col)
    elif k == 'circle':
        d.ellipse([ns[0]-ns[2]+ox, ns[1]-ns[2]+oy, ns[0]+ns[2]+ox, ns[1]+ns[2]+oy], fill=col)

def render(path, W, H, scale=1.0):
    root = ET.parse(path).getroot()
    doc = Doc(root, W, H)
    sw, sh = int(W*scale), int(H*scale)
    img = Image.new('RGBA', (W, H), (0,0,0,0))
    for el in root:
        if tag(el) == 'defs': continue
        draw_shape(img, el, 0, 0, doc)
    return img

def seam_report(img, name):
    W = img.size[0]
    px = img.load()
    worst = 0; worst_y = 0
    for y in range(img.size[1]):
        a = px[0, y]; b = px[W-1, y]
        diff = max(abs(a[i]-b[i]) for i in range(4))
        if diff > worst: worst, worst_y = diff, y
    status = "SEAMLESS" if worst == 0 else ("near-seamless" if worst <= 3 else "SEAM VISIBLE")
    print(f"  {name}: col[0] vs col[W-1] max channel diff = {worst} (at y={worst_y})  -> {status}")
    return worst

if __name__ == '__main__':
    layers = [
        ('park_bg_far', 'public/assets/env/park_bg_far.svg', 1280, 720),
        ('park_bg_near', 'public/assets/env/park_bg_near.svg', 1280, 360),
        ('ground_tile', 'public/assets/env/ground_tile.svg', 256, 160),
        ('park_fg_grass', 'public/assets/env/park_fg_grass.svg', 1280, 140),
    ]
    print("=== SEAM VERIFICATION (col[0] must equal col[W-1] for a perfectly periodic tile) ===")
    for name, path, W, H in layers:
        img = render(path, W, H)
        seam_report(img, name)
        # 2x-wide tiled preview (two copies side by side) + a red seam line between them
        tiled = Image.new('RGBA', (W*2, H), (0,0,0,0))
        tiled.alpha_composite(img, (0,0))
        tiled.alpha_composite(img, (W,0))
        # mark the seam
        ImageDraw.Draw(tiled).line([(W,0),(W,H)], fill=(255,0,0,255), width=0)
        tiled.save(f'/tmp/seam_{name}.png')
    print("  (wrote /tmp/seam_*.png with a 1px red seam marker between the two tiles)")

#!/usr/bin/env python3
"""Pure-Python (stdlib only) SVG-subset rasterizer for SEAM verification.
No PIL. Renders each env layer, asserts col[0]==col[W-1] (the tiling seam
condition), and writes a 2x-wide tiled PNG with a red seam marker for inspection."""
import re, math, struct, zlib
import xml.etree.ElementTree as ET

NS = '{http://www.w3.org/2000/svg}'
def tag(e): return e.tag.replace(NS, '')

def hx(c):
    c = c.strip().lstrip('#')
    if len(c) == 3: c = ''.join(ch*2 for ch in c)
    return (int(c[0:2],16), int(c[2:4],16), int(c[4:6],16), 255)

def stops_of(grad):
    out = []
    for s in grad:
        if tag(s) != 'stop': continue
        col = hx(s.get('stop-color','#000000'))
        out.append((float(s.get('offset','0')), col[0], col[1], col[2], float(s.get('stop-opacity','1'))))
    out.sort(); return out

def lerp_stops(st, t):
    if t <= st[0][0]: r=st[0]
    elif t >= st[-1][0]: r=st[-1]
    else:
        for i in range(len(st)-1):
            if st[i][0] <= t <= st[i+1][0]:
                a,b=st[i],st[i+1]; u=(t-a[0])/(b[0]-a[0]) if b[0]!=a[0] else 0
                return (a[1]+(b[1]-a[1])*u, a[2]+(b[2]-a[2])*u, a[3]+(b[3]-a[3])*u, a[4]+(b[4]-a[4])*u)
        r=st[-1]
    return (r[1],r[2],r[3],r[4])

# ---- framebuffer ----
class FB:
    def __init__(s,W,H): s.W=W;s.H=H;s.px=bytearray(W*H*4)
    def row(s,y): return y*s.W*4
    def set_span(s,x0,x1,y,col):
        if x0<0:x0=0
        if x1>s.W:x1=s.W
        if x0>=x1 or y<0 or y>=s.H: return
        off=s.row(y)+x0*4; n=x1-x0; s.px[off:off+n*4]=bytes(col)*n
    def blend_span(s,x0,x1,y,col):
        if x0<0:x0=0
        if x1>s.W:x1=s.W
        if x0>=x1 or y<0 or y>=s.H: return
        sa=col[3]/255.0; off=s.row(y); px=s.px
        for x in range(x0,x1):
            o=off+x*4; dr,dg,db,da=px[o],px[o+1],px[o+2],px[o+3]
            da1=da/255.0; oa=sa+da1*(1-sa)
            if oa<=0: out=(0,0,0,0)
            else:
                out=(int((col[0]*sa+dr*da1*(1-sa))/oa),
                     int((col[1]*sa+dg*da1*(1-sa))/oa),
                     int((col[2]*sa+db*da1*(1-sa))/oa), int(oa*255))
            px[o:o+4]=bytes(out)

def fill_poly(fb,pts,col):
    W,H=fb.W,fb.H
    ys=[p[1] for p in pts]
    if not ys: return
    y0=max(0,int(math.floor(min(ys)))); y1=min(H-1,int(math.ceil(max(ys))))
    n=len(pts)
    for y in range(y0,y1+1):
        yc=y+0.5; xs=[]
        for i in range(n):
            ax,ay=pts[i]; bx,by=pts[(i+1)%n]
            if (ay<=yc<by) or (by<=yc<ay):
                xs.append(ax+(yc-ay)/(by-ay)*(bx-ax))
        xs.sort()
        for i in range(0,len(xs)-1,2):
            a=int(math.ceil(xs[i])); b=int(math.floor(xs[i+1]))
            if a<=b: fb.set_span(a,b+1,y,col)

def fill_ellipse(fb,cx,cy,rx,ry,col):
    W,H=fb.W,fb.H
    x0=max(0,int(math.floor(cx-rx))); x1=min(W,int(math.ceil(cx+rx)))
    y0=max(0,int(math.floor(cy-ry))); y1=min(H,int(math.ceil(cy+ry)))
    ry2=ry*ry
    for y in range(y0,y1):
        dy=y-cy; dd=ry2-dy*dy
        if dd<0: continue
        dx=rx*math.sqrt(dd/ry2) if ry2 else 0
        xa=int(math.ceil(cx-dx)); xb=int(math.floor(cx+dx))
        if xa>xb: continue
        if col[3]==255: fb.set_span(xa,xb+1,y,col)
        else: fb.blend_span(xa,xb+1,y,col)

# ---- path sampling ----
def parse_cmds(d):
    cmds=re.findall(r'[MmLlHhVvCcQqSsTtZz]',d)
    nums=[float(x) for x in re.findall(r'-?\d*\.?\d+(?:[eE][-+]?\d+)?',d)]
    out=[]; ni=0
    for c in cmds:
        n={'Z':0,'z':0,'H':1,'h':1,'V':1,'v':1,'M':2,'m':2,'L':2,'l':2,'T':2,'t':2,'Q':4,'q':4,'S':4,'s':4,'C':6,'c':6}[c]
        out.append((c,nums[ni:ni+n])); ni+=n
    return out

def path_polys(d,ox=0.0,oy=0.0):
    polys=[]; poly=[]; x=y=0.0; sx=sy=0.0
    def cub(p0,p1,p2,p3,N=22):
        o=[]
        for i in range(N+1):
            t=i/N;mt=1-t;u=mt**3;v=3*mt*mt*t;w=3*mt*t*t;z=t**3
            o.append((u*p0[0]+v*p1[0]+w*p2[0]+z*p3[0], u*p0[1]+v*p1[1]+w*p2[1]+z*p3[1]))
        return o
    def qua(p0,p1,p2,N=16):
        o=[]
        for i in range(N+1):
            t=i/N;mt=1-t
            o.append((mt*mt*p0[0]+2*mt*t*p1[0]+t*t*p2[0], mt*mt*p0[1]+2*mt*t*p1[1]+t*t*p2[1]))
        return o
    for c,ns in parse_cmds(d):
        C=c.upper(); rel=c.islower()
        if C=='M':
            if poly: polys.append(poly)
            poly=[]; x,y=(ns[0]+ox,ns[1]+oy) if not rel else (x+ns[0],y+ns[1]); sx,sy=x,y; poly.append((x,y))
        elif C=='L':
            nx,ny=(ns[0]+ox,ns[1]+oy) if not rel else (x+ns[0],y+ns[1]); poly.append((nx,ny)); x,y=nx,ny
        elif C=='H':
            nx=ns[0]+ox if not rel else x+ns[0]; poly.append((nx,y)); x=nx
        elif C=='V':
            ny=ns[0]+oy if not rel else y+ns[0]; poly.append((x,ny)); y=ny
        elif C=='C':
            p0=(x,y)
            if not rel: pts=[(ns[0]+ox,ns[1]+oy),(ns[2]+ox,ns[3]+oy),(ns[4]+ox,ns[5]+oy)]
            else: pts=[(x+ns[0],y+ns[1]),(x+ns[2],y+ns[3]),(x+ns[4],y+ns[5])]
            poly+=cub(p0,pts[0],pts[1],pts[2]); x,y=pts[2]
        elif C=='Q':
            p0=(x,y)
            if not rel: pts=[(ns[0]+ox,ns[1]+oy),(ns[2]+ox,ns[3]+oy)]
            else: pts=[(x+ns[0],y+ns[1]),(x+ns[2],y+ns[3])]
            poly+=qua(p0,pts[0],pts[1]); x,y=pts[1]
        elif C=='Z':
            poly.append((sx,sy)); polys.append(poly); poly=[]; x,y=sx,sy
    if poly: polys.append(poly)
    return polys

# ---- PNG writer ----
def write_png(path,W,H,px):
    def chunk(t,data):
        return struct.pack('>I',len(data))+t+data+struct.pack('>I',zlib.crc32(t+data)&0xffffffff)
    raw=bytearray()
    for y in range(H):
        raw.append(0); raw+=px[y*W*4:(y+1)*W*4]
    open(path,'wb').write(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',W,H,8,6,0,0,0))
        +chunk(b'IDAT',zlib.compress(bytes(raw),9))+chunk(b'IEND',b''))

# ---- document ----
class Doc:
    def __init__(s,root):
        s.grads={}; s.sym={}
        for el in root.iter():
            if tag(el) in ('linearGradient','radialGradient'): s.grads['#'+el.get('id')]=el
            if tag(el)=='g' and el.get('id'): s.sym['#'+el.get('id')]=el

def grad_kind(st):  # returns ('v',) or ('r',)
    return None

def draw(fb,el,ox,oy,doc):
    k=tag(el)
    if k=='g':
        for ch in el: draw(fb,ch,ox,oy,doc); return
    if k=='use':
        href=el.get('href') or el.get(NS+'href'); sym=doc.sym.get(href)
        if sym is None: return
        m=re.search(r'translate\(([-\d.]+)[\s,]+([-\d.]+)\)',el.get('transform',''))
        tx,ty=(float(m.group(1)),float(m.group(2))) if m else (0,0)
        for ch in sym: draw(fb,ch,ox+tx,oy+ty,doc); return
    if k=='path':
        fill=el.get('fill','#000')
        if fill=='none': return
        col=hx(fill); col=(col[0],col[1],col[2],int(float(el.get('opacity','1'))*255))
        for poly in path_polys(el.get('d',''),ox,oy):
            if len(poly)>=3: fill_poly(fb,poly,col)
        return
    if k not in ('rect','ellipse','circle'): return
    if k=='rect': ns=[float(el.get(a,'0')) for a in('x','y','width','height')]
    elif k=='ellipse': ns=[float(el.get(a,'0')) for a in('cx','cy','rx','ry')]
    else: ns=[float(el.get(a,'0')) for a in('cx','cy','r')]
    fill=el.get('fill','#000'); op=float(el.get('opacity',el.get('fill-opacity','1')))
    if fill.startswith('url('):
        gid=re.search(r'url\((#[^)]+)\)',fill).group(1); g=doc.grads[gid]; sts=stops_of(g)
        if tag(g)=='linearGradient':  # vertical, objectBoundingBox
            x0,y0=ns[0]+ox,ns[1]+oy; h=ns[3]
            for py in range(int(y0),int(y0+h)):
                r,gg,b,a=lerp_stops(sts,(py-y0)/h if h else 0); a*=op
                col=(int(r),int(gg),int(b))
                if a>=0.999: fb.set_span(int(x0),int(x0+ns[2]),py,col)
                else: fb.blend_span(int(x0),int(x0+ns[2]),py,(col[0],col[1],col[2],int(a*255)))
        else:  # radial circle
            cx,cy,r=ns[0]+ox,ns[1]+oy,ns[2]
            for py in range(max(0,int(cy-r)),min(fb.H,int(cy+r+1))):
                for pxx in range(max(0,int(cx-r)),min(fb.W,int(cx+r+1))):
                    nx=(pxx-(cx-r))/(2*r); ny=(py-(cy-r))/(2*r)
                    d=math.hypot(nx-0.5,ny-0.5)/0.5
                    if d>1: continue
                    r2,gg,b,a=lerp_stops(sts,d); a*=op
                    if a<=0: continue
                    fb.blend_span(pxx,pxx+1,py,(int(r2),int(gg),int(b),int(a*255)))
        return
    col=hx(fill); col=(col[0],col[1],col[2],int(op*255))
    if k=='rect': fb.set_span for _
    if k=='rect':
        x0,y0,w,h=ns[0]+ox,ns[1]+oy,ns[2],ns[3]
        for py in range(int(y0),int(y0+h)):
            if col[3]==255: fb.set_span(int(x0),int(x0+w),py,col)
            else: fb.blend_span(int(x0),int(x0+w),py,col)
    elif k=='ellipse':
        fill_ellipse(fb,ns[0]+ox,ns[1]+oy,ns[2],ns[3],col)
    else:
        fill_ellipse(fb,ns[0]+ox,ns[1]+oy,ns[2],ns[2],col)

def render(path,W,H):
    root=ET.parse(path).getroot(); doc=Doc(root)
    fb=FB(W,H)
    for el in root:
        if tag(el)=='defs': continue
        draw(fb,el,0,0,doc)
    return fb

def seam(fb,name):
    W,H=fb.W,fb.H; px=fb.px; worst=0; wy=0
    for y in range(H):
        o0=y*W*4; o1=y*W*4+(W-1)*4
        for i in range(4):
            dd=abs(px[o0+i]-px[o1+i])
            if dd>worst: worst,wy=dd,y
    st='SEAMLESS' if worst==0 else ('near (<=3)' if worst<=3 else 'VISIBLE SEAM!!')
    print(f"  {name:14s} col[0] vs col[{W-1}] maxΔ={worst} (y={wy})  -> {st}")
    return worst

